package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var m, b int64
	fmt.Fscan(in, &m, &b)

	var ans int64 = 0

	// For each possible y2 (top side of rectangle)
	for y2 := int64(0); y2 <= b; y2++ {
		// Max x such that point (x, y2) lies on or under line: x + m*y2 <= m*b
		xMax := m*b - m*y2
		if xMax < 0 {
			continue
		}

		// Sum over rectangle [0..xMax] x [0..y2] of (x + y)
		// Sum_x = sum_{x=0}^{xMax} sum_{y=0}^{y2} x = (y2+1) * (xMax*(xMax+1)/2)
		// Sum_y = sum_{y=0}^{y2} sum_{x=0}^{xMax} y = (xMax+1) * (y2*(y2+1)/2)
		sumX := (y2 + 1) * (xMax * (xMax + 1) / 2)
		sumY := (xMax + 1) * (y2 * (y2 + 1) / 2)
		total := sumX + sumY

		if total > ans {
			ans = total
		}
	}

	fmt.Println(ans)
}
