package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var m, b int64
	fmt.Fscan(in, &m, &b)

	var ans int64 = 0

	for y := int64(0); y <= b; y++ {
		// x_max = m*(b - y)
		xMax := m * (b - y)

		// sum over x=0..xMax, y=0..yMax (yMax = y)
		// total bananas = sum_x sum_y (x + y)
		// = sum_x [ (y+1)*x + y*(y+1)/2 ]
		// = (y+1)*sum_x x + (xMax+1)*y*(y+1)/2
		// sum_x x = xMax*(xMax+1)/2

		yPlus1 := y + 1
		sumX := xMax * (xMax + 1) / 2
		part1 := yPlus1 * sumX
		part2 := (xMax + 1) * y * yPlus1 / 2
		total := part1 + part2

		if total > ans {
			ans = total
		}
	}

	fmt.Println(ans)
}
